using System;
using System.IO;
using System.IO.Compression;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;

namespace BlockchainContract
{
    public class FeatureFlags
    {
        public bool EnablePayloadCompression { get; set; } = true;
        public bool EnableNestedArchives { get; set; } = true;
        public bool StrictSizeValidation { get; set; } = true;
        public long MaxCompressedPayloadBytes { get; set; } = 10 * 1024 * 1024; // 10MB
        public long MaxDecompressedPayloadBytes { get; set; } = 100 * 1024 * 1024; // 100MB
        public int MaxNestingDepth { get; set; } = 3;
    }

    public class TransactionPayload
    {
        public byte[] Data { get; set; }
        public string Hash { get; set; }
        public int CompressionLevel { get; set; }
        public Dictionary<string, string> Metadata { get; set; } = new Dictionary<string, string>();
    }

    public class PayloadValidator
    {
        private readonly FeatureFlags _flags;
        private long _totalBytesProcessed;
        private int _currentDepth;

        public PayloadValidator(FeatureFlags flags)
        {
            _flags = flags ?? throw new ArgumentNullException(nameof(flags));
            _totalBytesProcessed = 0;
            _currentDepth = 0;
        }

        public bool ValidateCompressedSize(byte[] compressedData)
        {
            if (!_flags.StrictSizeValidation) return true;
            return compressedData.Length <= _flags.MaxCompressedPayloadBytes;
        }

        private string ComputeHash(byte[] data)
        {
            using (var sha = SHA256.Create())
            {
                var hash = sha.ComputeHash(data);
                return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
            }
        }

        public bool ValidateIntegrity(TransactionPayload payload)
        {
            var computed = ComputeHash(payload.Data);
            return string.Equals(computed, payload.Hash, StringComparison.OrdinalIgnoreCase);
        }

        private long GetDecompressedSize(byte[] compressedData)
        {
            // Estimate decompressed size by reading the gzip footer
            // which contains the original size mod 2^32
            if (compressedData.Length < 4) return 0;
            int last = compressedData.Length;
            return BitConverter.ToUInt32(compressedData, last - 4);
        }

        public byte[] SafeDecompress(byte[] compressedData, int depth = 0)
        {
            if (!_flags.EnablePayloadCompression)
                return compressedData;

            if (!ValidateCompressedSize(compressedData))
                throw new InvalidOperationException("Compressed payload exceeds maximum size");

            // Check nesting depth
            if (depth > _flags.MaxNestingDepth)
                throw new InvalidOperationException($"Maximum nesting depth {_flags.MaxNestingDepth} exceeded");

            // Pre-flight size check using gzip footer
            long estimatedSize = GetDecompressedSize(compressedData);
            if (_flags.StrictSizeValidation && estimatedSize > _flags.MaxDecompressedPayloadBytes)
                throw new InvalidOperationException("Estimated decompressed size exceeds limit");

            using (var inputStream = new MemoryStream(compressedData))
            using (var gzipStream = new GZipStream(inputStream, CompressionMode.Decompress))
            using (var outputStream = new MemoryStream())
            {
                byte[] buffer = new byte[8192];
                int bytesRead;
                long totalRead = 0;

                while ((bytesRead = gzipStream.Read(buffer, 0, buffer.Length)) > 0)
                {
                    totalRead += bytesRead;
                    _totalBytesProcessed += bytesRead;

                    // Size guard during decompression
                    if (_flags.StrictSizeValidation && totalRead > _flags.MaxDecompressedPayloadBytes)
                        throw new InvalidOperationException("Decompressed payload exceeds maximum size during extraction");

                    outputStream.Write(buffer, 0, bytesRead);
                }

                byte[] result = outputStream.ToArray();

                // Handle nested archives if feature enabled
                if (_flags.EnableNestedArchives && IsGzipData(result))
                {
                    return SafeDecompress(result, depth + 1);
                }

                return result;
            }
        }

        private bool IsGzipData(byte[] data)
        {
            return data.Length >= 2 && data[0] == 0x1F && data[1] == 0x8B;
        }
    }

    public class SmartContractExecutor
    {
        private readonly FeatureFlags _flags;
        private readonly PayloadValidator _validator;

        public SmartContractExecutor(FeatureFlags flags)
        {
            _flags = flags;
            _validator = new PayloadValidator(flags);
        }

        public byte[] ProcessTransaction(TransactionPayload payload)
        {
            if (payload == null)
                throw new ArgumentNullException(nameof(payload));

            if (!_validator.ValidateIntegrity(payload))
                throw new InvalidOperationException("Payload integrity check failed");

            byte[] processedData = payload.Data;

            if (_flags.EnablePayloadCompression && payload.CompressionLevel > 0)
            {
                processedData = _validator.SafeDecompress(payload.Data);
            }

            return processedData;
        }

        public FeatureFlags GetEffectiveFlags(Dictionary<string, string> overrides)
        {
            // Feature flags are immutable at runtime - no overrides allowed
            // This prevents attackers from weakening security controls
            var effective = new FeatureFlags
            {
                EnablePayloadCompression = _flags.EnablePayloadCompression,
                EnableNestedArchives = _flags.EnableNestedArchives,
                StrictSizeValidation = _flags.StrictSizeValidation,
                MaxCompressedPayloadBytes = _flags.MaxCompressedPayloadBytes,
                MaxDecompressedPayloadBytes = _flags.MaxDecompressedPayloadBytes,
                MaxNestingDepth = _flags.MaxNestingDepth
            };

            return effective;
        }

        public byte[] ProcessTransactionWithOverrides(TransactionPayload payload)
        {
            if (payload == null)
                throw new ArgumentNullException(nameof(payload));

            // Always use immutable flags - metadata cannot override security settings
            var effectiveFlags = GetEffectiveFlags(payload.Metadata);
            var validator = new PayloadValidator(effectiveFlags);

            if (!validator.ValidateIntegrity(payload))
                throw new InvalidOperationException("Payload integrity check failed");

            byte[] processedData = payload.Data;

            if (effectiveFlags.EnablePayloadCompression && payload.CompressionLevel > 0)
            {
                processedData = validator.SafeDecompress(payload.Data);
            }

            return processedData;
        }
    }
}
